// A button that downloads a PDF generated by the server.
//   <PdfButton url="/receipts/5/pdf" filename="receipt.pdf">Download PDF</PdfButton>
// The login token is sent automatically; if the server refuses (for example a blocked hall ticket) its message is shown.
import { useState } from 'react';
import { FileDown } from 'lucide-react';
import Button from './Button';
import { useToast } from '../hooks/useToast';
import { downloadPdf } from '../utils/download';

export default function PdfButton({ url, params, filename, children = 'Download PDF', variant = 'primary', ...rest }) {
  const toast = useToast();
  const [busy, setBusy] = useState(false);
  async function download() {
    setBusy(true);
    try { await downloadPdf(url, params, filename); } catch (err) { toast.error(err.message); } finally { setBusy(false); }
  }
  return <Button variant={variant} loading={busy} icon={<FileDown size={16} />} onClick={download} {...rest}>{children}</Button>;
}
